update public.learning_paths
set
  title = 'Social and Behavioral Determinants of Health',
  goal = 'Social and Behavioral Determinants of Health',
  summary = 'This course examines how social structures, policies, institutions, environments, relationships, stress processes, and behavior shape population health and inequity. Students learn to measure determinants, reason about causal pathways, interpret disparities without stigmatizing groups, engage communities, and design multilevel interventions. The course integrates social epidemiology, behavioral science, policy, equity, and public communication.',
  data = $sbdhjson${"slug": "social-and-behavioral-determinants-of-health", "title": "Social and Behavioral Determinants of Health", "description": "This course examines how social structures, policies, institutions, environments, relationships, stress processes, and behavior shape population health and inequity. Students learn to measure determinants, reason about causal pathways, interpret disparities without stigmatizing groups, engage communities, and design multilevel interventions. The course integrates social epidemiology, behavioral science, policy, equity, and public communication.", "topics": [{"id": "4a533441-e63b-4b7e-bb35-19eb76587b30", "type": "topic", "title": "Determinants Frameworks, Health Equity, and Causal Thinking", "description": "Establish how social conditions, power, institutions, environments, biology, and behavior interact to produce patterned health outcomes.", "children": [{"id": "fbcbf65e-3a5a-472e-8077-6a72dc536434", "type": "subtopic", "title": "Core frameworks", "description": "Students compare SDOH, social production, fundamental cause, ecosocial, and political-economy perspectives.", "children": [{"id": "e6d1e14c-8c98-4b5f-a981-02acb8af5c2b", "type": "concept", "title": "Upstream, midstream, and downstream determinants"}, {"id": "6b7737c4-58fb-4231-a88e-c7e222290904", "type": "concept", "title": "Structural, intermediary, and individual pathways"}, {"id": "823b520c-20db-4ba3-b8d4-eb4ccde90e0a", "type": "concept", "title": "Health difference, disparity, inequity, and equity"}]}, {"id": "2f6274df-43ce-4040-b7d3-0ceb42da861b", "type": "subtopic", "title": "Causal pathways", "description": "The point is mechanisms rather than determinant lists.", "children": [{"id": "5a5986da-ca43-49d8-9cb3-cb999a179290", "type": "concept", "title": "Material, psychosocial, behavioral, environmental, and healthcare pathways"}, {"id": "17093e3f-e0a7-4017-b498-fc47ae91d48e", "type": "concept", "title": "Mediation, moderation, feedback, and cumulative exposure"}, {"id": "5b496f4b-ee13-4e09-8ebc-e9a879c83f16", "type": "concept", "title": "Selection, reverse causation, and confounding"}]}, {"id": "bf781cf8-bfab-4dbf-81b8-2e0cdc0fcdd2", "type": "subtopic", "title": "Ethics and action", "description": "Students connect explanation to public responsibility.", "children": [{"id": "826812fa-4e86-47d0-8d6c-c6fa8b7f8bd1", "type": "concept", "title": "Human rights and social justice"}, {"id": "9c547bc1-adc5-403e-a72d-dff813d4854f", "type": "concept", "title": "Universal, targeted, and proportionate universal approaches"}, {"id": "47cb603f-e599-4b18-85a5-61b450fb245f", "type": "concept", "title": "Avoiding blame, stigma, and deficit framing"}]}]}, {"id": "7786f4dd-584d-40c3-b539-766965982e9f", "type": "topic", "title": "Measuring Social Conditions and Health Inequities", "description": "Use valid, transparent measures while recognizing that categories and datasets are socially produced.", "children": [{"id": "f82a8afb-1e3d-4dea-b032-87439368c42d", "type": "subtopic", "title": "Variables and indicators", "description": "Students operationalize complex constructs.", "children": [{"id": "3c31bf33-5d04-4e80-9b43-0277bac5377d", "type": "concept", "title": "Income, wealth, education, occupation, deprivation, and hardship"}, {"id": "ac56e4fa-6af8-4f56-bea7-57a042dd8000", "type": "concept", "title": "Individual, household, neighborhood, institutional, and policy measures"}, {"id": "aca9deb5-a4f8-46e5-82e1-00e4217fd381", "type": "concept", "title": "Absolute/relative and objective/subjective measures"}]}, {"id": "d89fb25b-6234-41b6-ad04-a36e216d2d81", "type": "subtopic", "title": "Inequality measurement", "description": "The goal is clear comparison across groups, places, and time.", "children": [{"id": "217ea71b-45ad-45b0-b18a-5a6ca20658aa", "type": "concept", "title": "Rates, ratios, differences, concentration, gradients, and population impact"}, {"id": "5591f667-b146-4646-9c28-a0907c4cfdf2", "type": "concept", "title": "Age standardization and denominator choice concepts"}, {"id": "a538068c-8967-41b8-a9d4-f2a4fe54e676", "type": "concept", "title": "Intersectional and small-area reporting"}]}, {"id": "35f861a2-5793-4c33-b00d-1bebde52bd64", "type": "subtopic", "title": "Data quality and ethics", "description": "Students examine missingness, misclassification, privacy, and harm.", "children": [{"id": "9878eb34-837f-4695-a0f5-2d75ad913b54", "type": "concept", "title": "Self-identification and administrative categories"}, {"id": "4ad466bb-1193-4046-a92d-2eaf4a13101f", "type": "concept", "title": "Data disaggregation and unstable estimates"}, {"id": "c765be10-c087-4442-b63b-d3e8c0a18882", "type": "concept", "title": "Governance, consent, sovereignty, and deficit narratives"}]}]}, {"id": "8c5e42e9-a053-4a25-a5db-c648bfd47141", "type": "topic", "title": "Socioeconomic Position, Income, Wealth, and Poverty", "description": "Explain how command over resources, security, status, and opportunity shapes exposure and health across a gradient.", "children": [{"id": "1efebd6e-289c-4f2b-a753-f0f0c831ac1b", "type": "subtopic", "title": "Dimensions of socioeconomic position", "description": "Students distinguish income, wealth, education, occupation, and class.", "children": [{"id": "1b1e2695-fdf8-4b70-ab47-71b8cf3adc34", "type": "concept", "title": "Current resources versus accumulated assets/debt"}, {"id": "b5a11af0-df9c-4838-b117-8270f84dbd18", "type": "concept", "title": "Employment status, occupational prestige, and working conditions"}, {"id": "e4847266-693f-4ac3-b092-ce1ed47464b1", "type": "concept", "title": "Subjective social status and relative deprivation"}]}, {"id": "cf3b0ee2-a0bd-455d-bc07-8f872a12af9f", "type": "subtopic", "title": "Health pathways", "description": "The point is why gradients persist beyond extreme poverty.", "children": [{"id": "88522954-2094-49d2-a8a0-5ae80bb3ce7b", "type": "concept", "title": "Material conditions and access to essentials"}, {"id": "19dbf4e3-e6c9-4d8e-b2bd-bbe9baeed9fc", "type": "concept", "title": "Stress, control, status, and social participation"}, {"id": "1b93fb94-26e1-4b34-88dc-cf8e78484af0", "type": "concept", "title": "Health behavior opportunities and healthcare access"}]}, {"id": "62dcf18a-ef02-4f4d-9f39-c47ea2fdd3ab", "type": "subtopic", "title": "Policy responses", "description": "Students compare income and service interventions.", "children": [{"id": "c3371784-c7ee-4d7a-88b9-42d2dfc7bda7", "type": "concept", "title": "Minimum wage, tax credits, cash transfers, and social insurance"}, {"id": "a0824f32-c8b6-4982-aa45-c7ea655e4e37", "type": "concept", "title": "Debt, benefits cliffs, and administrative burden"}, {"id": "97f94aed-7dcc-4ac7-be48-b2b8134f967f", "type": "concept", "title": "Universal services and anti-poverty policy"}]}]}, {"id": "d3c23a58-ca6e-4381-b32a-79e7050ce502", "type": "topic", "title": "Structural Racism, Ethnicity, Migration, and Discrimination", "description": "Analyze racialized health inequities as products of historical and contemporary systems rather than biological race.", "children": [{"id": "c1b5f37e-a04a-49a3-98db-5a2e43e8e8b0", "type": "subtopic", "title": "Structural pathways", "description": "Students trace policy and institutional mechanisms.", "children": [{"id": "a56849fb-26a4-4554-8084-db078a1b3f91", "type": "concept", "title": "Segregation, housing, education, labor, criminal legal, and environmental policy"}, {"id": "4b13fbc9-3cc1-4335-aea9-0d917fa3ea4e", "type": "concept", "title": "Wealth extraction and unequal investment"}, {"id": "304448fd-8472-48f2-aca2-90c6a0c04044", "type": "concept", "title": "Healthcare access, quality, and algorithmic bias"}]}, {"id": "263e0c01-6a68-499b-b7ff-8219e21f46ca", "type": "subtopic", "title": "Discrimination and embodiment", "description": "The goal is connecting interpersonal/institutional exposure to health.", "children": [{"id": "1e08b699-190d-403a-8aa6-78cb35528695", "type": "concept", "title": "Acute/chronic discrimination and vigilance"}, {"id": "39d9d8c5-4bdd-4608-816d-1ea7ff944c5d", "type": "concept", "title": "Stress physiology, mental health, and care avoidance"}, {"id": "f0098d62-c1d7-41af-ad24-aec79c075c60", "type": "concept", "title": "Colorism, xenophobia, and language discrimination"}]}, {"id": "4b811cf8-81b3-44f5-99ec-c57a78275713", "type": "subtopic", "title": "Migration and ethnicity", "description": "Students avoid treating diverse populations as homogeneous.", "children": [{"id": "b7c9d611-a1dc-4e93-9030-218ad1358e26", "type": "concept", "title": "Nativity, legal status, displacement, and acculturation contexts"}, {"id": "b9e78010-9c40-42e5-8004-5ec83a09ed2e", "type": "concept", "title": "Healthy-immigrant selection and erosion concepts"}, {"id": "f75384fc-a34f-4fb6-b673-e82a815ecae7", "type": "concept", "title": "Data categories, within-group variation, and community strengths"}]}]}, {"id": "793ceab7-a6cb-4f31-adb1-66e0539ce087", "type": "topic", "title": "Gender, Sexuality, and Health", "description": "Examine how gender systems, sexual orientation, reproductive governance, roles, violence, and care work influence health.", "children": [{"id": "2a6b2734-6191-4196-ae55-4b73fb8aa600", "type": "subtopic", "title": "Gender as social structure", "description": "Students distinguish sex-related biology from gendered exposure and power.", "children": [{"id": "0309d069-af54-4cee-8779-22dacf65219d", "type": "concept", "title": "Norms, roles, occupations, income, and unpaid care"}, {"id": "f8f9a3a7-c19d-413a-8b66-dc68fc048bb0", "type": "concept", "title": "Masculinities, femininities, and gender diversity"}, {"id": "126fad07-81e4-4df6-9b34-d52ac33dc928", "type": "concept", "title": "Institutional policy and discrimination"}]}, {"id": "a5e9d742-57bc-440c-9cd6-a94510bf408c", "type": "subtopic", "title": "Sexual and gender minority health", "description": "The point is minority stress and structural access, not identity as risk.", "children": [{"id": "f90ebf30-e65e-4b58-8a6f-5c756fabc413", "type": "concept", "title": "Stigma, rejection, violence, and resilience"}, {"id": "1f9e9be0-a2a7-44cd-8aff-d0f80c0b72b3", "type": "concept", "title": "Affirming care, insurance, and geographic access"}, {"id": "d7fbd5c4-8248-4fe0-85dc-f2e18bcd7c7a", "type": "concept", "title": "Measurement, confidentiality, and inclusive data"}]}, {"id": "f90b3e5d-cf5f-42b6-b9c5-9ab2ead01001", "type": "subtopic", "title": "Life and reproductive health", "description": "Students analyze autonomy and policy context.", "children": [{"id": "82e58c6c-5b0d-440f-9b5a-879099b5463f", "type": "concept", "title": "Reproductive justice and maternal health"}, {"id": "8ea0eea8-9fe9-48f3-885a-76c625ead622", "type": "concept", "title": "Gender-based violence and safety"}, {"id": "52e0ff52-a621-4953-a2ff-1a42d21140d5", "type": "concept", "title": "Caregiving, family policy, and aging"}]}]}, {"id": "c14dba94-8ab9-4ad9-9ebf-9b9aaeb50224", "type": "topic", "title": "Life Course, Development, and Intergenerational Health", "description": "Understand how timing, duration, accumulation, and linked lives shape health trajectories.", "children": [{"id": "f3cc402b-8198-4e31-8de9-d61e380a0d6d", "type": "subtopic", "title": "Life-course models", "description": "Students compare critical period, accumulation, pathway, and social mobility models.", "children": [{"id": "a2138351-149f-4a00-89ac-3eb767958d62", "type": "concept", "title": "Prenatal, childhood, adolescence, adulthood, and aging"}, {"id": "0c8839d0-4f4b-4e85-99d0-fbd0f0ce8802", "type": "concept", "title": "Timing, dose, duration, and reversibility"}, {"id": "2f82e44a-ff13-40d4-9993-05ee86d4a64d", "type": "concept", "title": "Turning points and sensitive periods"}]}, {"id": "b8d0ec14-7e26-4d68-8f86-4d98c695e85d", "type": "subtopic", "title": "Childhood conditions", "description": "The goal is connecting early environments to development without determinism.", "children": [{"id": "18a9b276-131d-4c59-8b39-b71421ed7ac3", "type": "concept", "title": "Nutrition, housing, education, safety, relationships, and adversity"}, {"id": "6e00e1f9-5b6b-4757-beec-f306e7ba5405", "type": "concept", "title": "Protective factors and resilience"}, {"id": "21179d89-112c-4105-ba84-fa662f64a68d", "type": "concept", "title": "Toxic stress and developmental opportunity"}]}, {"id": "b7a961c9-c0d3-4b2d-81d7-b22e0d283954", "type": "subtopic", "title": "Intergenerational processes", "description": "Students trace resources and risks across generations.", "children": [{"id": "f8749d26-d343-46b7-8ea6-7fd35b08aee8", "type": "concept", "title": "Wealth, neighborhood, education, caregiving, and policy"}, {"id": "782c614c-9c82-4e71-a89f-87a5c3f2dcea", "type": "concept", "title": "Trauma and discrimination"}, {"id": "533065f6-6212-4194-970f-d948b6fb35be", "type": "concept", "title": "Intergenerational mobility and reparative policy"}]}]}, {"id": "256cbd16-22d6-433f-9a6f-1de79b2f78c4", "type": "topic", "title": "Education, Health Literacy, and Information Environments", "description": "Analyze education as a determinant and design communication environments people can use.", "children": [{"id": "06e92f09-c81b-4150-82d1-a56629cee988", "type": "subtopic", "title": "Education pathways", "description": "Students connect schooling to knowledge, credentials, work, resources, and social networks.", "children": [{"id": "1830b03f-109a-43fb-8378-25a34aea2cda", "type": "concept", "title": "Early childhood and school quality"}, {"id": "e6b21d17-1eac-4ec8-9df5-80edb9d32f5a", "type": "concept", "title": "Segregation, discipline, disability access, and completion"}, {"id": "c7280164-593b-47f3-a7ad-bd9ff678b275", "type": "concept", "title": "Adult education and lifelong learning"}]}, {"id": "9fc191c0-bf81-4966-b931-9fc0a13756d8", "type": "subtopic", "title": "Health literacy", "description": "The point is system responsibility rather than labeling individuals.", "children": [{"id": "6937352f-0ee6-4298-946a-0d6d449ac5a0", "type": "concept", "title": "Personal and organizational health literacy"}, {"id": "bfc0d2fd-b435-4a2d-b687-6ca71976254c", "type": "concept", "title": "Numeracy, navigation, and decision demands"}, {"id": "467340a2-9b29-4a2e-8f4b-0ed32f5db7fd", "type": "concept", "title": "Plain language, teach-back, translation, and accessibility"}]}, {"id": "d891983e-6a65-41e9-a05e-a02a3c4844ba", "type": "subtopic", "title": "Information environments", "description": "Students assess media, misinformation, and digital systems.", "children": [{"id": "b12079c3-7963-4c89-8e8b-18f34211a58d", "type": "concept", "title": "Commercial and social-media influence"}, {"id": "a2009a2b-240c-4446-987f-b728396950e1", "type": "concept", "title": "Trust, messengers, and information overload"}, {"id": "34163a3a-30cd-442d-b4b3-9d8bcad0c76d", "type": "concept", "title": "Digital literacy and algorithmic exposure"}]}]}, {"id": "2693047d-acf2-4f8a-97ca-dcc88d60c498", "type": "topic", "title": "Work, Employment, and Labor Conditions", "description": "Explain how job access, security, control, hazards, benefits, and labor power affect health.", "children": [{"id": "c29a7d87-efa5-474a-ad99-90d2e99b774f", "type": "subtopic", "title": "Employment conditions", "description": "Students distinguish employment status from job quality.", "children": [{"id": "85cc63e4-90bb-499e-ac91-48c0b46e898b", "type": "concept", "title": "Wages, schedules, benefits, leave, security, and precarity"}, {"id": "5a61d3e4-9f36-4fdb-ac88-8d6e27f46d93", "type": "concept", "title": "Control, demand, support, and effort–reward imbalance"}, {"id": "9152bfbd-f879-447d-a82a-3e35633f2752", "type": "concept", "title": "Discrimination, harassment, and workplace violence"}]}, {"id": "e056e6fc-629e-4448-9155-be8f7aad4629", "type": "subtopic", "title": "Occupational exposure", "description": "The goal is linking work organization and hazards.", "children": [{"id": "aad0e2d0-a8bc-47b3-b22a-be0471ba3b38", "type": "concept", "title": "Physical, chemical, biological, ergonomic, and psychosocial hazards"}, {"id": "f5486185-d00a-4beb-a162-ce725aef8fcb", "type": "concept", "title": "Injury, chronic disease, mental health, and fatigue"}, {"id": "e9b8c3d4-940b-4934-943a-f62d770a3467", "type": "concept", "title": "Gig, informal, migrant, and essential work"}]}, {"id": "69116508-d2ee-4262-8a23-dcba82dc6fca", "type": "subtopic", "title": "Policy and worker power", "description": "Students examine protections and enforcement.", "children": [{"id": "9aa79422-66e1-4cd6-9a03-50d1de35c24f", "type": "concept", "title": "Occupational standards and workers' compensation"}, {"id": "b96241ed-1df8-41db-b255-f67bac833dda", "type": "concept", "title": "Paid leave, predictable scheduling, and living wage"}, {"id": "2a2b366b-ada3-4ddf-8fd1-f486e8c92bf9", "type": "concept", "title": "Unions, worker centers, and participatory safety"}]}]}, {"id": "d75f3bda-cce8-4264-ad08-c90beb48722b", "type": "topic", "title": "Housing, Neighborhoods, and Place", "description": "Understand how housing conditions, affordability, segregation, mobility, and local resources shape health.", "children": [{"id": "f0741d2c-299d-48bd-8eab-2dbdc4444a84", "type": "subtopic", "title": "Housing pathways", "description": "Students connect home to exposure, stability, stress, and care.", "children": [{"id": "d47f7636-8b66-4896-b8a6-9298fa3f459c", "type": "concept", "title": "Quality, crowding, ventilation, pests, lead, mold, and injury"}, {"id": "e7642ab8-8d18-451a-aa15-ecccb7cb1a8e", "type": "concept", "title": "Affordability, eviction, homelessness, and displacement"}, {"id": "95be505b-d656-4588-95ce-7e9cad70dcfd", "type": "concept", "title": "Accessibility, energy burden, and climate resilience"}]}, {"id": "357bd680-80ae-4574-b576-a4cd997193ee", "type": "subtopic", "title": "Neighborhood context", "description": "The point is place as both exposure and resource.", "children": [{"id": "315d6c0b-3028-41d0-a1a6-b866196de3e9", "type": "concept", "title": "Safety, green space, services, food, schools, transport, and healthcare"}, {"id": "0a685f84-a2e7-4820-8275-58618344c2d3", "type": "concept", "title": "Segregation, redlining, zoning, and investment"}, {"id": "25e7ae03-97ba-4bcf-be91-ccee7bedc523", "type": "concept", "title": "Collective efficacy, belonging, and stigma"}]}, {"id": "bc3b564c-5cc0-4907-b8c4-4527244e5837", "type": "subtopic", "title": "Place-based action", "description": "Students compare policies while watching for displacement.", "children": [{"id": "3cf0fae5-8f3c-4353-ac44-0fa79b8e87b0", "type": "concept", "title": "Housing-first, vouchers, public/social housing, and tenant protection"}, {"id": "9fd2be47-c2a8-439d-b35a-3058c3e388fe", "type": "concept", "title": "Healthy homes and code enforcement"}, {"id": "22669ef5-9614-4485-902c-711c049865bd", "type": "concept", "title": "Community development, anti-displacement, and health impact assessment"}]}]}, {"id": "8bb0ec00-0876-457e-9a7a-09b7311f2222", "type": "topic", "title": "Food, Transportation, and Material Access", "description": "Examine systems that shape whether people can obtain food, mobility, utilities, and other essentials.", "children": [{"id": "3efb06ea-b42f-4107-b32b-7452f56a7f23", "type": "subtopic", "title": "Food systems", "description": "Students move beyond individual diet choice.", "children": [{"id": "db39cf76-736c-43d3-99f5-26812c7880b0", "type": "concept", "title": "Food security, affordability, quality, culture, and time"}, {"id": "e36d693e-90e6-4ab4-b98d-a522cd75d444", "type": "concept", "title": "Retail, marketing, agriculture, labor, and school food"}, {"id": "975f5c13-6b9a-4ed9-9b02-95304c65a191", "type": "concept", "title": "Nutrition assistance and emergency food"}]}, {"id": "ad1dbc98-0f85-4533-a73c-d8a56a05dc4b", "type": "subtopic", "title": "Transportation", "description": "The goal is access to work, care, education, food, and social life.", "children": [{"id": "8a702cbb-2df5-4bf1-9715-af0ffecc3e93", "type": "concept", "title": "Public transit, active transport, car dependence, and rural access"}, {"id": "c167606a-276d-4d1f-8c89-2b26f463a456", "type": "concept", "title": "Cost, time, disability accessibility, and safety"}, {"id": "38896e9e-d03f-41be-bc4c-81023a33f068", "type": "concept", "title": "Transport-related pollution and injury"}]}, {"id": "34e60c97-9aea-42b5-b170-47bc97d4564d", "type": "subtopic", "title": "Material hardship", "description": "Students understand interacting resource constraints.", "children": [{"id": "f6cea362-22c0-4cfd-b0d3-c723f08e118a", "type": "concept", "title": "Utilities, childcare, clothing, medication, and hygiene"}, {"id": "33c35cef-0813-4cee-b34f-8d47b75f3040", "type": "concept", "title": "Trade-offs, scarcity, and administrative burden"}, {"id": "d5f01ed9-b4de-499b-9ddd-9980e76f009d", "type": "concept", "title": "Integrated benefits and community resource navigation"}]}]}, {"id": "1f6ba3e6-0bf5-4166-98cf-8dec11b23659", "type": "topic", "title": "Digital Access and Technology as Determinants", "description": "Treat digital connectivity, design, data systems, and algorithmic decisions as emerging social determinants.", "children": [{"id": "d775a06b-189d-451d-adb6-dc6b5b131655", "type": "subtopic", "title": "Digital divide", "description": "Students distinguish access, affordability, devices, skills, and support.", "children": [{"id": "0347e6db-d4c6-4595-8d5f-7a54e84908a2", "type": "concept", "title": "Broadband and mobile coverage"}, {"id": "d2fe45fe-c6b6-4a3f-948b-aaccf480af1d", "type": "concept", "title": "Reliable devices, private space, and accessibility"}, {"id": "40e8d879-c989-4973-a60e-b886470a9560", "type": "concept", "title": "Rural, income, age, language, and disability disparities"}]}, {"id": "b8e585f7-1bb2-40cf-905c-a6b76b18b77f", "type": "subtopic", "title": "Digital health access", "description": "The point is who can use and benefit from technology.", "children": [{"id": "4ebcb4ed-fdfc-45fd-88a5-5fbb05396686", "type": "concept", "title": "Telehealth, portals, remote monitoring, and 