alth"}, {"id": "eca96bf4-2d2e-493d-83e9-820e60004d6a", "type": "concept", "title": "Displacement, infrastructure, and insurance"}, {"id": "2b9c064f-e959-4477-b548-465b9afdeb75", "type": "concept", "title": "Mitigation, adaptation, resilience, and just transition"}]}, {"id": "7ff904d4-b944-4ee9-970f-d05157ce15ff", "type": "subtopic", "title": "Environmental justice practice", "description": "Students center affected communities and procedural justice.", "children": [{"id": "fb321e91-0a6b-4d08-bf1a-a8337c5635c8", "type": "concept", "title": "Community science and right-to-know"}, {"id": "4640f9d2-72d3-4065-a095-efe30b9f9f77", "type": "concept", "title": "Health impact assessment and cumulative-impact screening"}, {"id": "8c0d8b3f-64d1-4b70-87ee-9c1c08fba2ea", "type": "concept", "title": "Indigenous sovereignty, land, and intergenerational responsibility"}]}]}, {"id": "9904f5be-f528-4328-974e-9fd43ee25bc4", "type": "topic", "title": "Healthcare Access, Quality, and Structural Barriers", "description": "Understand healthcare as one determinant among many and analyze access beyond insurance coverage.", "children": [{"id": "30624795-d8c2-4a2c-a2f2-99ccde38da48", "type": "subtopic", "title": "Dimensions of access", "description": "Students examine availability, affordability, accommodation, acceptability, and appropriateness.", "children": [{"id": "ee4eed4d-cb6a-4812-8275-fff3658387ff", "type": "concept", "title": "Coverage and benefit design"}, {"id": "e3a9f74b-0ad5-47e0-b246-9abccff36bad", "type": "concept", "title": "Geography, workforce, hours, transport, and waiting"}, {"id": "80d9d8e4-2b83-4b98-b29b-544d94ce84c2", "type": "concept", "title": "Language, disability, culture, trust, and discrimination"}]}, {"id": "4bf80d72-cc2a-4326-9b96-1bcfdcf4e1c9", "type": "subtopic", "title": "Quality and disparities", "description": "The point is unequal treatment within care systems.", "children": [{"id": "3f6840c9-1c31-4e73-ad94-efab76bdd3ac", "type": "concept", "title": "Diagnostic delay, undertreatment, pain, maternal care, and referral patterns"}, {"id": "43cc2f7e-ad2c-4f68-a313-8a2932ecc6b1", "type": "concept", "title": "Implicit/explicit bias and structural workflows"}, {"id": "dcfc5f6f-f842-43ec-b9d2-c3a525da7778", "type": "concept", "title": "Patient experience and safety"}]}, {"id": "7117a380-4b2b-4466-ac82-3a44f4bb24ab", "type": "subtopic", "title": "System responses", "description": "Students compare strategies and limits.", "children": [{"id": "6d9ac232-c859-45a0-b073-eaf60eacd0a6", "type": "concept", "title": "Community health centers and safety net"}, {"id": "722d222c-7bd3-43ff-8af6-98f0c4aad3dd", "type": "concept", "title": "Workforce diversity, interpreters, navigation, and community health workers"}, {"id": "3b020e9b-5a3b-4c1c-8528-a7734540548f", "type": "concept", "title": "Payment, accountability, and equity measurement"}]}]}, {"id": "f771701a-d967-4ab2-b0ec-f0dea4680df4", "type": "topic", "title": "Social Relationships, Networks, and Community Context", "description": "Explain how connection, isolation, social support, norms, cohesion, and collective efficacy influence health.", "children": [{"id": "04895a67-bfac-44b0-ad06-b4815a35182c", "type": "subtopic", "title": "Social ties and support", "description": "Students distinguish network structure from supportive function.", "children": [{"id": "40f665a8-a19b-4fcf-aeed-f0cbe5c81a69", "type": "concept", "title": "Emotional, informational, instrumental, and appraisal support"}, {"id": "d393bacc-e881-465f-a373-f4d2620bcbc8", "type": "concept", "title": "Network size, density, diversity, and reciprocity"}, {"id": "e261039e-45d7-46ac-a3f7-0d3cd9c33474", "type": "concept", "title": "Isolation, loneliness, caregiving, and bereavement"}]}, {"id": "31272463-1ceb-4295-aa41-4afc278015ee", "type": "subtopic", "title": "Norms and diffusion", "description": "The goal is understanding how behaviors and information spread.", "children": [{"id": "63a7204f-26a9-4fb7-b095-946af98167e8", "ty